// sound.js - 音效與背景音樂(全域 window.Sound, 不用 ES module)
// 事件名、呼叫時機與 opts 見 sound.md; RD 只需讀 sound.md。
(function () {
  'use strict';

  // ---- 拍子常數(與 spec 一致) ----
  var BPM = 150;
  var BEAT_SEC = 60 / BPM;          // 0.4 秒
  var LOOP_BARS = 8;
  var LOOP_BEATS = LOOP_BARS * 4;   // 32 拍
  var LOOP_SEC = LOOP_BEATS * BEAT_SEC; // 12.8 秒
  var SONG_START_BEAT = -4;         // 預備拍第 -4 拍 = 歌曲第一小節第一拍
  var PCM_RATE = 22050;
  var MUSIC_VOL = 0.45;

  // ---- 一次性音效定義 ----
  // pcm: 內嵌 PCM 名稱; file: 沒有 Web Audio 時的退路檔; vol: 相對音量
  var SFX = {
    countIn:   { pcm: 'count_in_pluck',     file: 'count_in_pluck.mp3',     vol: 0.8 },
    onBeat:    { pcm: 'on_beat_glass',      file: 'on_beat_glass.mp3',      vol: 1.0 },
    beatChain: { pcm: 'beat_chain_powerup', file: 'beat_chain_powerup.mp3', vol: 0.9 },
    catch:     { pcm: 'catch_confirm',      file: 'catch_confirm.mp3',      vol: 0.45 },
    netSwap:   { pcm: 'net_swap_phaser_up', file: 'net_swap_phaser_up.mp3', vol: 0.4 },
    expire:    { pcm: 'expire_phaser_down', file: 'expire_phaser_down.mp3', vol: 0.5 },
    clear:     { pcm: 'clear_jingle',       file: 'clear_jingle.mp3',       vol: 0.75 },
    danger:    { pcm: 'danger_jingle',      file: 'danger_jingle.mp3',      vol: 0.65 }
  };
  var MUSIC = { main: true };

  // 預備拍: 剩 4 / 3 / 2 / 1 拍時的音高(do re mi so, 越接近開始越高)
  var COUNT_IN_RATE = { 4: 1.0, 3: 1.1225, 2: 1.2599, 1: 1.4983 };

  // ---- 狀態 ----
  var ctx = null;
  var master = null, sfxBus = null, musicBus = null;
  var buffers = {};
  var inited = false;
  var muted = false;
  var pools = {};          // 沒有 Web Audio 時的 HTMLAudio 播放池
  var lastPlayed = {};     // 事件名 -> 最近一次播放的 performance 時間(毫秒)
  var latencyComp = true;  // 音樂是否補償輸出延遲(讓「聽到的」拍子對齊時鐘)

  var music = {
    name: null,       // 目前選定的曲名(暫停中也保留)
    source: null,
    gain: null,
    buffer: null,
    startCtx: 0,      // source 開始的 ctx 時間
    beatAtStart: 0,   // source 開始那一刻對應的「時鐘拍」(已扣掉延遲補償)
    playing: false
  };

  function nowMs() {
    return (typeof performance !== 'undefined' && performance.now) ? performance.now() : Date.now();
  }

  // ---- PCM 解碼(同步, 不經 decodeAudioData) ----
  function b64ToFloat(b64) {
    var bin = atob(b64);
    var n = bin.length >> 1;
    var out = new Float32Array(n);
    for (var i = 0; i < n; i++) {
      var lo = bin.charCodeAt(i * 2), hi = bin.charCodeAt(i * 2 + 1);
      var v = (hi << 8) | lo;
      if (v >= 32768) v -= 65536;
      out[i] = v / 32768;
    }
    return out;
  }

  function makeBuffer(data, rate) {
    var b = ctx.createBuffer(1, data.length, rate);
    if (b.copyToChannel) b.copyToChannel(data, 0);
    else b.getChannelData(0).set(data);
    return b;
  }

  // ---- 背景音樂: 程式合成, 150 BPM, 4/4, 8 小節循環 ----
  // 每拍一記大鼓(重拍落在每一拍), 反拍只有很輕的 hi-hat; 低音與旋律音都起在拍上。
  function synthMusic(sr) {
    var L = Math.round(LOOP_SEC * sr);
    var outL = new Float32Array(L), outR = new Float32Array(L);
    var beatN = BEAT_SEC * sr;

    var seed = 12345;
    function rnd() { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff * 2 - 1; }

    // 帶限波表(避免方波刺耳的鋸齒)
    function table(kind) {
      var N = 2048, t = new Float32Array(N), H = 15;
      for (var i = 0; i < N; i++) {
        var p = i / N, s = 0;
        for (var h = 1; h <= H; h++) {
          if (kind === 'square') { if (h % 2) s += Math.sin(2 * Math.PI * h * p) / h; }
          else if (kind === 'pulse25') { s += Math.sin(Math.PI * h * 0.25) * Math.cos(2 * Math.PI * h * (p - 0.125)) / h; }
          else if (kind === 'tri') { if (h % 2) s += (((h - 1) / 2) % 2 ? -1 : 1) * Math.sin(2 * Math.PI * h * p) / (h * h); }
        }
        t[i] = s;
      }
      var m = 0; for (i = 0; i < N; i++) m = Math.max(m, Math.abs(t[i]));
      for (i = 0; i < N; i++) t[i] /= m;
      return t;
    }
    var SQ = table('square'), PU = table('pulse25'), TR = table('tri');

    function add(idx, v, pan) { // pan -1..1
      idx = ((idx % L) + L) % L;  // 尾音繞回開頭 -> 循環接縫無斷點
      outL[idx] += v * (1 - Math.max(0, pan));
      outR[idx] += v * (1 + Math.min(0, pan));
    }
    function tone(tab, freq, startSec, durSec, amp, attack, decayTau, pan) {
      var s0 = Math.round(startSec * sr), n = Math.round((durSec + decayTau * 3) * sr);
      var ph = 0, inc = freq * 2048 / sr, aN = Math.max(1, attack * sr), dN = durSec * sr;
      for (var i = 0; i < n; i++) {
        var env = i < aN ? i / aN : 1;
        if (i > dN) env *= Math.exp(-(i - dN) / (decayTau * sr));
        add(s0 + i, tab[(ph | 0) & 2047] * env * amp, pan);
        ph += inc;
      }
    }
    function kick(beatIdx, amp) {
      var s0 = Math.round(beatIdx * beatN), n = Math.round(0.22 * sr), ph = 0;
      for (var i = 0; i < n; i++) {
        var t = i / sr;
        var f = 45 + 110 * Math.exp(-t / 0.03);
        ph += 2 * Math.PI * f / sr;
        var env = Math.exp(-t / 0.07) * Math.min(1, i / 8);
        var click = i < 0.004 * sr ? 0.35 * (1 - i / (0.004 * sr)) : 0;
        add(s0 + i, (Math.sin(ph) * env + click) * amp, 0);
      }
    }
    function noiseHit(startSec, amp, tau, hp, pan) {
      var s0 = Math.round(startSec * sr), n = Math.round(tau * 5 * sr), prev = 0, prevOut = 0;
      for (var i = 0; i < n; i++) {
        var x = rnd();
        var y = hp * (prevOut + x - prev); prev = x; prevOut = y; // 一階高通
        add(s0 + i, y * amp * Math.exp(-i / (tau * sr)) * Math.min(1, i / 4), pan);
      }
    }
    function hz(midi) { return 440 * Math.pow(2, (midi - 69) / 12); }

    // 和弦進行(每 2 小節一個): Am F C G
    var chords = [[57, 60, 64], [53, 57, 60], [48, 52, 55], [55, 59, 62]];
    var roots = [45, 41, 48, 43];
    // 旋律(每格一拍; null = 延長前一音, 0 = 休止)
    var mel = [
      69, 0, 72, 76,   74, 72, 69, null,
      69, 72, 77, 76,  72, null, 69, 0,
      67, 72, 76, 79,  76, 74, 72, null,
      71, 74, 79, 74,  76, null, null, 0
    ];

    for (var b = 0; b < LOOP_BEATS; b++) {
      var bar = Math.floor(b / 4), inBar = b % 4, ci = Math.floor(bar / 2) % 4;
      var t = b * BEAT_SEC;
      // 大鼓: 每一拍
      kick(b, inBar === 0 ? 0.95 : 0.85);
      // 小鼓(輕): 第 2、4 拍, 仍在拍上
      if (inBar === 1 || inBar === 3) noiseHit(t, 0.22, 0.045, 0.6, 0);
      // hi-hat: 拍上較響, 反拍很輕(不強調反拍)
      noiseHit(t, 0.10, 0.012, 0.95, 0.3);
      noiseHit(t + BEAT_SEC / 2, 0.04, 0.010, 0.95, 0.3);
      // 低音: 每拍一音, 起在拍上
      tone(TR, hz(roots[ci] + (inBar === 2 ? 12 : 0)), t, 0.22, 0.42, 0.003, 0.05, 0);
      // 琶音: 16 分音符, 每拍第一個較響
      var ch = chords[ci];
      for (var k = 0; k < 4; k++) {
        var note = ch[(b * 4 + k) % 3] + 12;
        tone(PU, hz(note), t + k * BEAT_SEC / 4, 0.05, k === 0 ? 0.075 : 0.04, 0.002, 0.03, -0.35);
      }
      // 旋律
      var m = mel[b];
      if (m) {
        var len = 1;
        while (b + len < LOOP_BEATS && mel[b + len] === null) len++;
        tone(SQ, hz(m), t, len * BEAT_SEC * 0.85, 0.11, 0.004, 0.06, 0.25);
      }
    }

    // 軟限幅 + 正規化
    var peak = 0, i2;
    for (i2 = 0; i2 < L; i2++) {
      outL[i2] = Math.tanh(outL[i2] * 1.2); outR[i2] = Math.tanh(outR[i2] * 1.2);
      peak = Math.max(peak, Math.abs(outL[i2]), Math.abs(outR[i2]));
    }
    var g = peak > 0 ? 0.9 / peak : 1;
    for (i2 = 0; i2 < L; i2++) { outL[i2] *= g; outR[i2] *= g; }
    return { L: outL, R: outR, length: L };
  }

  // ---- 初始化 ----
  function init() {
    if (inited) {
      if (ctx && ctx.state === 'suspended' && ctx.resume) { try { ctx.resume(); } catch (e) {} }
      return;
    }
    inited = true;
    var AC = (typeof window !== 'undefined') && (window.AudioContext || window.webkitAudioContext);
    if (AC) {
      try {
        ctx = new AC({ latencyHint: 'interactive' });
      } catch (e) {
        try { ctx = new AC(); } catch (e2) { ctx = null; }
      }
    }
    if (ctx) {
      try {
        master = ctx.createGain();
        master.gain.value = muted ? 0 : 1;
        master.connect(ctx.destination);
        sfxBus = ctx.createGain(); sfxBus.connect(master);
        musicBus = ctx.createGain(); musicBus.gain.value = MUSIC_VOL; musicBus.connect(master);
        for (var k in PCM_DATA) {
          if (Object.prototype.hasOwnProperty.call(PCM_DATA, k)) buffers[k] = makeBuffer(b64ToFloat(PCM_DATA[k]), PCM_RATE);
        }
        var mu = synthMusic(ctx.sampleRate);
        var mb = ctx.createBuffer(2, mu.length, ctx.sampleRate);
        mb.getChannelData(0).set(mu.L);
        mb.getChannelData(1).set(mu.R);
        buffers.__music_main = mb;
        if (ctx.state === 'suspended' && ctx.resume) ctx.resume();
      } catch (e) {
        ctx = null;
      }
    }
    if (!ctx) buildPools();
  }

  function buildPools() {
    if (typeof Audio === 'undefined') return;
    for (var name in SFX) {
      if (!Object.prototype.hasOwnProperty.call(SFX, name)) continue;
      var arr = [];
      for (var i = 0; i < 4; i++) {
        try { var a = new Audio('audio/assets/' + SFX[name].file); a.preload = 'auto'; arr.push(a); } catch (e) {}
      }
      pools[name] = { list: arr, next: 0 };
    }
  }

  // ---- 一次性音效 ----
  function playBuffer(bufName, vol, rate, delay, pan) {
    var buf = buffers[bufName];
    if (!buf) return;
    var src = ctx.createBufferSource();
    src.buffer = buf;
    src.playbackRate.value = rate || 1;
    var g = ctx.createGain();
    g.gain.value = vol;
    src.connect(g);
    var node = g;
    if (pan && ctx.createStereoPanner) {
      var p = ctx.createStereoPanner();
      p.pan.value = Math.max(-1, Math.min(1, pan));
      g.connect(p); node = p;
    }
    node.connect(sfxBus);
    src.start(ctx.currentTime + (delay || 0));
  }

  function play(name, opts) {
    try {
      if (!inited) return;
      if (!Object.prototype.hasOwnProperty.call(SFX, name)) return;
      var def = SFX[name];
      opts = opts || {};
      var t = nowMs();
      var rate = 1, delay = 0, vol = def.vol;
      var pan = (typeof opts.x === 'number') ? ((opts.x - 640) / 640) * 0.6 : 0;

      if (name === 'countIn') {
        rate = COUNT_IN_RATE[opts.left] || 1;
        if (opts.left === 1) vol = Math.min(1, vol * 1.25);
      } else if (name === 'onBeat') {
        // 同一刻已響過整串 -> 整串已含同款亮音, 不再疊
        if (t - (lastPlayed.beatChain || -1e9) < 60) return;
        var step = Math.max(1, Math.min(4, opts.step | 0 || 1));
        rate = [1, 1.1225, 1.2599, 1.3348][step - 1];
      } else if (name === 'netSwap') {
        // 與捕捉同一刻 -> 稍晚 70 毫秒, 讓兩聲分得開
        if (t - (lastPlayed.catch || -1e9) < 50) delay = 0.07;
      } else if (name === 'danger') {
        if (t - (lastPlayed.danger || -1e9) < 1000) return;
      }
      lastPlayed[name] = t;

      if (ctx) {
        playBuffer(def.pcm, vol, rate, delay, pan);
        if (name === 'beatChain') {
          // 疊一層高八度的踩拍亮音, 讓起音立即且與單次踩拍明顯不同
          // 同一刻已響過單次踩拍(送進網節點)-> 那聲就當第一層, 不再重疊
          if (t - (lastPlayed.onBeat || -1e9) >= 60) playBuffer('on_beat_glass', 0.8, 1.5, 0, pan);
          playBuffer('on_beat_glass', 0.6, 2.0, 0.1, pan);
        }
        return;
      }
      // 退路: HTMLAudio 播放池
      var pool = pools[name];
      if (!pool || !pool.list.length || muted) return;
      var a = pool.list[pool.next];
      pool.next = (pool.next + 1) % pool.list.length;
      a.volume = Math.min(1, vol);
      if ('playbackRate' in a) a.playbackRate = rate;
      try { a.currentTime = 0; } catch (e) {}
      var pr = a.play();
      if (pr && pr.catch) pr.catch(function () {});
    } catch (e) { /* 不讓音效錯誤影響遊戲 */ }
  }

  // ---- 背景音樂 ----
  function songOffsetForBeat(beat) {
    var sec = (beat - SONG_START_BEAT) * BEAT_SEC;
    return ((sec % LOOP_SEC) + LOOP_SEC) % LOOP_SEC;
  }

  function outLatency() {
    if (!ctx) return 0;
    var v = (ctx.outputLatency || 0) + (ctx.baseLatency || 0);
    return isFinite(v) ? v : 0;
  }

  function stopSource(fadeSec) {
    if (!music.source) return;
    var s = music.source, g = music.gain;
    music.source = null; music.gain = null; music.playing = false;
    try {
      var t = ctx.currentTime;
      g.gain.cancelScheduledValues(t);
      g.gain.setValueAtTime(g.gain.value, t);
      g.gain.linearRampToValueAtTime(0, t + fadeSec);
      s.stop(t + fadeSec + 0.02);
    } catch (e) { try { s.stop(); } catch (e2) {} }
  }

  // 讓音樂「此刻」對到時鐘拍 beat(可為小數)
  function startAt(name, beat, fadeIn) {
    var buf = buffers['__music_' + name];
    if (!buf) return;
    var comp = latencyComp ? outLatency() : 0;
    var t0 = ctx.currentTime;
    // 延遲補償: 聲音要過 comp 秒才被聽到, 所以從「beat + comp」的位置開始播
    var offset = songOffsetForBeat(beat + comp / BEAT_SEC);
    var src = ctx.createBufferSource();
    src.buffer = buf;
    src.loop = true;
    src.loopStart = 0;
    src.loopEnd = buf.duration;
    var g = ctx.createGain();
    src.connect(g); g.connect(musicBus);
    g.gain.setValueAtTime(fadeIn ? 0 : 1, t0);
    if (fadeIn) g.gain.linearRampToValueAtTime(1, t0 + fadeIn);
    src.start(t0, offset);
    music.source = src; music.gain = g; music.buffer = buf;
    music.startCtx = t0;
    music.beatAtStart = beat;
    music.playing = true;
    music.name = name;
  }

  function playMusic(name, opts) {
    try {
      if (!inited || !ctx) return;
      if (!Object.prototype.hasOwnProperty.call(MUSIC, name)) return;
      var beat = (opts && typeof opts.beat === 'number') ? opts.beat : SONG_START_BEAT;
      var hadOther = music.source && music.name !== name;
      stopSource(hadOther ? 0.3 : 0.015);
      startAt(name, beat, 0.015);
    } catch (e) {}
  }

  function stopMusic() {
    try {
      if (!ctx) return;
      stopSource(0.15);
      music.name = null;
    } catch (e) {}
  }

  function pauseMusic() {
    try {
      if (!ctx) return;
      stopSource(0.03);
    } catch (e) {}
  }

  // 恢復 / 校正: 讓音樂此刻對到時鐘拍 beat
  function seekMusic(beat) {
    try {
      if (!ctx || !music.name || typeof beat !== 'number') return;
      stopSource(0.015);
      startAt(music.name, beat, 0.015);
    } catch (e) {}
  }

  // 目前音樂(聽到的)對應的時鐘拍; 沒在播回 null
  function getMusicBeat() {
    if (!ctx || !music.playing) return null;
    return music.beatAtStart + (ctx.currentTime - music.startCtx) / BEAT_SEC;
  }

  // 每拍(或每幀)由 RD 傳入時鐘拍; 偏差超過容許值就把音樂對回時鐘。回傳偏差秒數(音樂 - 時鐘)
  function syncMusic(beat, toleranceSec) {
    try {
      if (!ctx || !music.playing || typeof beat !== 'number') return 0;
      var tol = (typeof toleranceSec === 'number') ? toleranceSec : 0.04;
      var drift = (getMusicBeat() - beat) * BEAT_SEC;
      if (Math.abs(drift) > tol) seekMusic(beat);
      return drift;
    } catch (e) { return 0; }
  }

  // ---- 靜音 ----
  function setMuted(b) {
    muted = !!b;
    try {
      if (master && ctx) {
        var t = ctx.currentTime;
        master.gain.cancelScheduledValues(t);
        master.gain.setValueAtTime(master.gain.value, t);
        master.gain.linearRampToValueAtTime(muted ? 0 : 1, t + 0.02);
      }
      if (muted) {
        for (var k in pools) {
          if (!Object.prototype.hasOwnProperty.call(pools, k)) continue;
          for (var i = 0; i < pools[k].list.length; i++) { try { pools[k].list[i].pause(); } catch (e) {} }
        }
      }
    } catch (e) {}
  }
  function isMuted() { return muted; }

  window.Sound = {
    init: init,
    play: play,
    playMusic: playMusic,
    stopMusic: stopMusic,
    setMuted: setMuted,
    isMuted: isMuted,
    // 拍子對齊介面(見 sound.md「背景音樂與拍子時鐘」)
    pauseMusic: pauseMusic,
    resumeMusic: seekMusic,
    seekMusic: seekMusic,
    syncMusic: syncMusic,
    getMusicBeat: getMusicBeat,
    getOutputLatency: outLatency,
    setMusicLatencyCompensation: function (on) { latencyComp = !!on; },
    BPM: BPM,
    BEAT_SEC: BEAT_SEC,
    LOOP_BEATS: LOOP_BEATS,
    SONG_START_BEAT: SONG_START_BEAT,
    // 測試用: 回傳合成好的音樂資料(不需 AudioContext)
    _synthMusic: synthMusic
  };

  // ---- 內嵌短音效(16-bit PCM, 單聲道, 22050 Hz, base64)----
  var PCM_DATA = {
    count_in_pluck: "",
    on_beat_glass: "",
    beat_chain_powerup: "",
    catch_confirm: "",
    net_swap_phaser_up: "",
    expire_phaser_down: "",
    clear_jingle: "",
    danger_jingle: ""
  };
})();
